style:
.tw-cosolar--qingci.resume-paper {
  color: #26383a;
}

.tw-cosolar--qingci.resume-paper .paper-header {
  position: relative;
  display: block;
  margin: 0 0 7mm;
  padding: 0 0 5mm;
  border: none;
  border-bottom: 1px solid #dcebea;
}

.tw-cosolar--qingci.resume-paper .paper-header::before {
  content: "";
  position: absolute;
  top: calc(var(--paper-mt, 15mm) * -1);
  left: calc(var(--paper-ml, 15mm) * -1);
  right: calc(var(--paper-mr, 15mm) * -1);
  height: 2mm;
  background: #2b7f83;
  print-color-adjust: exact;
}

.tw-cosolar--qingci.resume-paper .paper-header__main {
  padding-right: 33mm;
}

.tw-cosolar--qingci.resume-paper .paper-photo {
  position: absolute;
  top: 0;
  right: 0;
  width: 26mm;
  height: 34mm;
  border: 0.5mm solid #cfe4e2;
  border-radius: 1.2mm;
  box-shadow: none;
  print-color-adjust: exact;
}

.tw-cosolar--qingci.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #eef7f6;
  color: #2b7f83;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 600;
}

.tw-cosolar--qingci.resume-paper .paper-name {
  color: #1d4448;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2);
  letter-spacing: 0.06em;
}

.tw-cosolar--qingci.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #6f8f90;
}

.tw-cosolar--qingci.resume-paper .paper-role {
  margin-top: 1.3mm;
  color: #2b7f83;
  font-weight: 600;
}

.tw-cosolar--qingci.resume-paper .paper-role::before {
  content: "求职意向：";
  color: #85a3a4;
  font-weight: 400;
  font-size: calc(var(--paper-base-size) * 0.92);
}

.tw-cosolar--qingci.resume-paper .paper-contacts--labeled {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.2mm 8mm;
  margin-top: 3mm;
  padding-top: 2.8mm;
  border-top: 1px solid #e3f0ef;
  color: #345054;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-cosolar--qingci.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-cosolar--qingci.resume-paper .paper-contact__label {
  color: #7f9b9c;
}

.tw-cosolar--qingci.resume-paper .paper-section {
  margin-bottom: 4.6mm;
}

.tw-cosolar--qingci.resume-paper .paper-section .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.2mm;
  padding: 1.2mm 3mm;
  background: #e6f3f1;
  border-radius: 1.6mm;
  color: #1f5b60;
  font-size: calc(var(--paper-base-size) * 1);
  letter-spacing: 0.1em;
  print-color-adjust: exact;
}

.tw-cosolar--qingci.resume-paper .paper-section .paper-section__icon {
  display: grid;
  place-items: center;
  width: 5mm;
  height: 5mm;
  border: none;
  border-radius: 1.2mm;
  background: #2b7f83;
  color: #fff;
}

.tw-cosolar--qingci.resume-paper .paper-section .paper-section__icon svg {
  width: 60%;
  height: 60%;
}

.tw-cosolar--qingci.resume-paper .paper-section .paper-section__title::after {
  content: none;
}

.tw-cosolar--qingci.resume-paper .paper-section .paper-section__body {
  margin-top: 2.2mm;
  padding: 2.6mm 3mm;
  background: #f5faf9;
  border-radius: 1.6mm;
  color: #2f4244;
  print-color-adjust: exact;
}

.tw-cosolar--qingci.resume-paper .paper-section .paper-item-title {
  color: #1e3a3d;
}

.tw-cosolar--qingci.resume-paper .paper-section .paper-item-period {
  color: #5d7f80;
  font-weight: 600;
}

.tw-cosolar--qingci.resume-paper .paper-section .paper-item-sub {
  color: #4a6668;
}

.tw-cosolar--qingci.resume-paper .paper-section .paper-note__tag {
  color: #2b7f83;
}

.tw-cosolar--qingci.resume-paper .paper-section .paper-skill {
  border-bottom-color: #e4f0ef;
}

.tw-cosolar--qingci.resume-paper .paper-section .paper-skill__level {
  color: #2b7f83;
}

.tw-cosolar--qingci.resume-paper .paper-footer {
  border-top: 1px solid #dcebea;
  color: #759192;
}
